
@font-face{font-family:'S-Core Dream';font-style:normal;font-weight:300;font-display:swap;src:url(data:font/woff2;base64,) format('woff2');}
@font-face{font-family:'S-Core Dream';font-style:normal;font-weight:400;font-display:swap;src:url(data:font/woff2;base64,) format('woff2');}
@font-face{font-family:'S-Core Dream';font-style:normal;font-weight:500;font-display:swap;src:url(data:font/woff2;base64,) format('woff2');}
@font-face{font-family:'S-Core Dream';font-style:normal;font-weight:700;font-display:swap;src:url(data:font/woff2;base64,) format('woff2');}
@font-face{font-family:'S-Core Dream';font-style:normal;font-weight:900;font-display:swap;src:url(data:font/woff2;base64,) format('woff2');}


:root{
  --ink:#15171a; --ink-2:#4c5257; --muted:#8c9296; --faint:#b4b9ba;
  --hair:#e2e3e0; --hair-2:#ebece9; --hair-3:#f3f4f1;
  --panel:#ffffff; --rail:#e9ebe3; --tint:#f5f6f4;
  --green:#175243; --green-tint:#eef3f1; --amber:#9a5b00; --track:#e9eae6;
  /* 신뢰도 3구간 — 뚜렷한 신호등 색 */
  --conf-high:#0a5c3e; --conf-high-tint:#e5efe9;
  --conf-mid:#565f64;  --conf-mid-tint:#ecedea;
  --conf-low:#8f2116;  --conf-low-tint:#f6e3e0;

  --ease:cubic-bezier(.22,.61,.36,1);
  --dur-fast:.16s; --dur-base:.28s; --dur-slow:.5s;
}
:root[data-theme="dark"]{
  --ink:#eef0f2; --ink-2:#c7ccd1; --muted:#8f979d; --faint:#5c6469;
  --hair:#2a2e33; --hair-2:#23272b; --hair-3:#1d2024;
  --panel:#15171a; --rail:#1a1d21; --tint:#1a1d21;
  --green:#5cbf9a; --green-tint:#1a2620; --amber:#d69a4a; --track:#2a2e33;
  /* 신뢰도 3구간 — 다크 대비용 */
  --conf-high:#3fb98b; --conf-high-tint:#122720;
  --conf-mid:#9aa2a8;  --conf-mid-tint:#22262a;
  --conf-low:#d9584a;  --conf-low-tint:#2d1512;
}
*{box-sizing:border-box;margin:0;padding:0}
body{
  font-family:'S-Core Dream',-apple-system,BlinkMacSystemFont,'Apple SD Gothic Neo','Malgun Gothic','Segoe UI',Roboto,'Noto Sans KR',sans-serif;
  font-weight:400;background:var(--panel);color:var(--ink);
  line-height:1.6;letter-spacing:-.005em;-webkit-font-smoothing:antialiased;
}
a{color:inherit;text-decoration:none}
svg text{font-family:inherit}

/* ---------- 시안 헤더 ---------- */
.deck{border-bottom:1px solid var(--ink);padding:16px 30px;
  display:flex;align-items:baseline;gap:14px;flex-wrap:wrap}
.deck h1{font-size:13px;font-weight:900;letter-spacing:.01em}
.deck .v{font-size:10.5px;font-weight:300;color:var(--muted)}
/* 로고 아이콘(LogoMark.jsx) — SVG라 var(--green)이 다크모드에서 자동으로 민트로 바뀝니다.
   글자 크기에 맞춰 spot마다(사이드바/드로어 nm, 상단바 brand2, 모바일 상단바 m-logo)
   높이만 다르게 줍니다. */
.logo-mark{flex:none;display:block;height:20px;width:20px}
.deck .capbox{margin-left:auto;display:flex;align-items:baseline;gap:11px;
  max-width:640px}
.deck .pri{font-size:10px;font-weight:900;letter-spacing:.08em;color:var(--green);flex:none}
.deck .cap{font-size:11.5px;font-weight:300;color:var(--muted);line-height:1.6}

/* ---------- 앱 셸 ---------- */
.app{display:grid;grid-template-columns:216px 1fr;min-height:100vh}
.side{background:var(--rail);border-right:1px solid var(--hair);
  padding:26px 18px 22px;display:flex;flex-direction:column}
.brand .eb{font-size:9.5px;font-weight:300;letter-spacing:.1em;color:var(--faint)}
.brand .nm{display:flex;align-items:center;gap:7px;
  font-size:18px;font-weight:900;letter-spacing:-.02em;margin-top:3px}
.brand .rule{width:19px;height:2px;background:var(--green);margin-top:10px}
.side nav{margin-top:28px;display:flex;flex-direction:column;gap:1px}
.side .lb{font-size:9.5px;font-weight:700;letter-spacing:.13em;color:var(--faint);
  padding:0 10px;margin:20px 0 7px}
.side nav:first-of-type .lb:first-child{margin-top:0}
.side a{font-size:13px;font-weight:400;color:var(--ink-2);padding:7px 10px;
  border-radius:6px;position:relative;cursor:pointer}
.side a:hover{color:var(--ink)}
.side a.on{font-weight:700;color:var(--ink);background:#eceee9}
:root[data-theme="dark"] .side a.on{background:var(--tint)}
.side a.on::before{content:"";position:absolute;left:-18px;top:8px;bottom:8px;
  width:2px;background:var(--green)}
.side a.off{color:var(--faint);cursor:default}
.side .foot{margin-top:auto;padding-top:20px;border-top:1px solid var(--hair);
  font-size:10px;font-weight:300;color:var(--faint);line-height:1.9;
  display:flex;align-items:flex-end;gap:12px}
.side .foot .who{margin-left:auto;width:27px;height:27px;border-radius:50%;
  background:var(--green);color:#fff;font-size:11px;font-weight:700;
  display:flex;align-items:center;justify-content:center}

.main{min-width:0;padding:32px 40px 80px;max-width:1180px}
.view{display:none}
.view.on{display:block}

/* ---------- 페이지 헤더 ---------- */
.ph{display:flex;align-items:baseline;gap:14px;flex-wrap:wrap;
  padding-bottom:16px;border-bottom:1px solid var(--ink)}
.ph h2{font-size:23px;font-weight:900;letter-spacing:-.03em;line-height:1.15}
.ph h2.ph-logo{display:flex;align-items:center;line-height:1}
.ph h2.ph-logo img{height:38px;width:auto;display:block}
.ph .dt{font-size:12px;font-weight:500;color:var(--muted)}
.ph .st{margin-left:auto;font-size:11.5px;font-weight:300;color:var(--muted)}
.ph .st b{font-weight:700;color:var(--green)}

/* ---------- 구역 ---------- */
.sec{padding:30px 0;border-bottom:1px solid var(--hair)}
.sec:last-child{border-bottom:0}
.sh{display:flex;align-items:baseline;gap:12px;margin-bottom:18px}
.sh .t{font-size:9.5px;font-weight:700;letter-spacing:.14em;color:var(--faint)}
.sh .c{font-size:10.5px;font-weight:900;color:var(--ink-2)}
.sh .s{font-size:11px;font-weight:300;color:var(--faint)}
.sh .r{margin-left:auto;font-size:11px;font-weight:300;color:var(--muted)}
.sh .r a{color:var(--green);font-weight:700}

/* ---------- 파이프라인 ---------- */
.pipe{display:flex;align-items:baseline;gap:12px;flex-wrap:wrap;
  padding:14px 0;border-top:1px solid var(--hair);border-bottom:1px solid var(--hair);
  margin:22px 0}
.pipe .st{display:flex;align-items:baseline;gap:7px}
.pipe .st .n{font-size:12.5px;font-weight:700}
.pipe .st .n::before{content:"✓";color:var(--green);margin-right:5px;font-weight:900}
.pipe .st .tm{font-size:10.5px;font-weight:300;color:var(--faint)}
.pipe .ar{color:var(--faint);font-size:11px}
.pipe .nx{margin-left:auto;font-size:10.5px;font-weight:300;color:var(--muted)}

/* ---------- 검색 ---------- */
.search{display:flex;align-items:center;gap:14px;padding:13px 17px;
  border:1.5px solid var(--ink);border-radius:10px;margin-bottom:6px}
.search .ph2{flex:1;min-width:0;font:inherit;font-size:14px;font-weight:300;color:var(--ink);
  background:none;border:none;outline:none;padding:0}
.search .ph2::placeholder{color:var(--faint);font-weight:300}
.search .go{font:inherit;font-size:12.5px;font-weight:700;color:#fff;background:var(--green);
  border:none;padding:7px 18px;border-radius:20px;cursor:pointer;flex:none;
  transition:transform var(--dur-fast) var(--ease),opacity var(--dur-fast) var(--ease)}
.search .go:hover{transform:translateY(-1px);opacity:.92}
:root[data-theme="dark"] .search .go{color:#0d1512}
.search-status{display:flex;align-items:center;gap:10px;font-size:11.5px;color:var(--muted);
  margin:2px 2px 10px}
.search-status a{font-weight:700;color:var(--green);cursor:pointer}
.search-hide{display:none!important}
@media (max-width:520px){
  .search .ph2{font-size:12.5px}
  .search .go{padding:6px 14px;font-size:11.5px}
}

/* ---------- KPI ---------- */
.kpi{display:grid;grid-template-columns:repeat(4,1fr)}
.kpi > div{padding:0 26px}
.kpi > div:first-child{padding-left:0}
.kpi > div:last-child{padding-right:0}
.kpi > div + div{border-left:1px solid var(--hair-2)}
.kpi .k{font-size:11.5px;font-weight:500;color:var(--muted);margin-bottom:9px}
.kpi .v{font-size:33px;font-weight:900;letter-spacing:-.035em;line-height:1}
.kpi .v.txt{font-size:21px;letter-spacing:-.025em}
.kpi .d{font-size:11px;font-weight:300;color:var(--faint);margin-top:8px}
.kpi .d b{color:var(--green);font-weight:700}

/* ---------- 차트 ---------- */
.chart{margin-top:4px}
.chart svg{width:100%;height:auto;display:block}
.chart .grid line{stroke:var(--hair-3);stroke-width:1}
.chart .grid line.ax{stroke:var(--hair)}
.chart text.yl,.chart text.xl{font-size:9.5px;font-weight:300;fill:var(--faint)}
.chart text.yl{text-anchor:end}
.chart text.xl{text-anchor:middle}
.chart .bars rect{fill:var(--track)}
.chart .bars rect.now{fill:var(--hair)}
.chart .area{fill:var(--green-tint)}
.chart .line{fill:none;stroke:var(--green);stroke-width:1.8;
  stroke-linejoin:round;stroke-linecap:round}
.chart .dots circle{fill:var(--panel);stroke:var(--green);stroke-width:1.4}
.chart .now-dot{fill:var(--green)}
.chart text.now{font-size:11px;font-weight:900;fill:var(--green);text-anchor:end}
.chart-legend{display:flex;gap:20px;flex-wrap:wrap;margin-top:14px;
  padding-top:12px;border-top:1px solid var(--hair-3);
  font-size:10.5px;font-weight:300;color:var(--muted)}
.chart-legend b{font-weight:700;color:var(--ink-2)}
.chart-legend .mk{display:inline-block;width:14px;height:2px;background:var(--green);
  vertical-align:3px;margin-right:6px}
.chart-legend .mk.bar{height:8px;width:8px;background:var(--track);vertical-align:0}

/* ---------- 분할 ---------- */
.split{display:grid;grid-template-columns:1fr 1fr;gap:46px}
.split > div:first-child{padding-right:46px;border-right:1px solid var(--hair)}

/* ---------- 카테고리 막대 ---------- */
.catrow{display:grid;grid-template-columns:1fr auto;align-items:center;
  gap:20px;padding:14px 0;border-bottom:1px solid var(--hair-3)}
.catrow:last-child{border-bottom:0}
.catrow .nm{font-size:13.5px;font-weight:700}
.catrow .nm .issue{display:block;font-size:12px;font-weight:400;color:var(--ink-2);margin-top:3px}
.catrow .nm .cnt{display:block;font-size:11px;font-weight:300;color:var(--faint);margin-top:2px}
.trk{height:5px;background:var(--track);border-radius:3px;overflow:hidden}
.trk i{display:block;height:100%;background:var(--green);border-radius:3px}
.trk i.am{background:var(--amber)}
.trk i.mu{background:var(--faint)}
.trk i.hi{background:var(--conf-high)}
.trk i.mid{background:var(--conf-mid)}
.trk i.low{background:var(--conf-low)}
.catrow .pc{font-size:11.5px;font-weight:800;text-align:right;white-space:nowrap}
.catrow .pc.hi{color:var(--conf-high)}
.catrow .pc.mid{color:var(--conf-mid)}
.catrow .pc.low{color:var(--conf-low)}

/* ---------- 키워드 ---------- */
.kwlist{display:flex;flex-direction:column}
.kwrow{font-size:14px;font-weight:500;color:var(--ink-2);padding:9px 0;
  border-bottom:1px solid var(--hair-3);display:flex;align-items:baseline}
.kwrow:last-child{border-bottom:0}
.kwrow:first-child{color:var(--green);font-weight:700}
.kwrow .h{color:var(--faint);font-weight:700;margin-right:5px}
.kwrow:first-child .h{color:var(--green)}
.kwrow .ct{margin-left:auto;font-size:10.5px;font-weight:300;color:var(--faint)}

/* ---------- 이슈 행 (리포트) ---------- */
.rows{border-top:1px solid var(--ink)}
.row{display:grid;grid-template-columns:120px 1fr 150px;gap:26px;padding:26px 0;
  border-bottom:1px solid var(--hair);align-items:start}
.tr{display:flex;flex-direction:column;align-items:flex-start;gap:7px}
/* 신뢰도 = 구간색 점 + 라벨 + 점수를 한 덩어리 pill 로 통일 */
.tr .l{display:inline-flex;align-items:center;gap:6px;line-height:1;
  font-size:11.5px;font-weight:700;letter-spacing:-.01em;
  color:var(--conf-high);background:var(--conf-high-tint);padding:6px 10px;border-radius:20px;
  border:1px solid color-mix(in srgb,var(--conf-high) 26%,transparent)}
.tr .l i{width:6px;height:6px;border-radius:50%;background:currentColor;flex:none}
.tr .n{font-size:10.5px;font-weight:300;color:var(--faint);line-height:1.3}
.tr.mid .l{color:var(--conf-mid);background:var(--conf-mid-tint);border-color:color-mix(in srgb,var(--conf-mid) 26%,transparent)}
.tr.low .l{color:var(--conf-low);background:var(--conf-low-tint);border-color:color-mix(in srgb,var(--conf-low) 26%,transparent)}
.tr.non .l{color:var(--faint);background:transparent;border-color:var(--hair)}
.row .ct{font-size:10px;font-weight:700;color:var(--muted);letter-spacing:.09em}
.row h3{font-size:16.5px;font-weight:700;letter-spacing:-.025em;line-height:1.4;margin:5px 0 7px}
.row h3.mu{font-weight:400;color:var(--ink-2)}
.row p{font-size:12.5px;font-weight:300;color:var(--muted);line-height:1.75;max-width:620px}
.row .meta{text-align:right}
.row .meta .s{font-size:11px;font-weight:500;color:var(--ink-2)}
.row .meta .s.doc{color:var(--green);font-weight:700}
.row .meta .s.doc::before{content:"";display:inline-block;width:5px;height:5px;
  border-radius:50%;background:var(--green);margin-right:6px;vertical-align:1px}
.row .meta .w{display:block;font-size:11px;font-weight:300;color:var(--muted);margin-top:7px}
.row.empty{border-left:2px dashed var(--hair);padding-left:16px}
.legend{margin-top:20px;padding-top:13px;border-top:1px solid var(--hair);
  display:flex;gap:22px;flex-wrap:wrap;font-size:10.5px;font-weight:300;color:var(--muted)}
.legend b{font-weight:700;color:var(--ink-2)}
.legend .lvl-btn{cursor:pointer;padding:2px 6px;border-radius:5px;
  transition:opacity var(--dur-fast) var(--ease),background var(--dur-fast) var(--ease)}
.legend .lvl-btn:hover{background:var(--tint)}
.legend .lvl-btn.off{opacity:.35}
.kwrow{cursor:pointer;transition:color var(--dur-fast) var(--ease)}
.kwrow:hover{color:var(--green)}
.legend .sw{display:inline-block;width:9px;height:9px;border-radius:2px;margin-right:6px;vertical-align:0}
.legend .sw.hi{background:var(--conf-high)}
.legend .sw.md{background:var(--conf-mid)}
.legend .sw.lo{background:var(--conf-low)}

/* ---------- 리포트 다운로드 / 보관함 ---------- */
.dlbar{display:flex;align-items:center;justify-content:flex-end;gap:10px;
  margin-top:22px;padding-top:16px;border-top:1px solid var(--hair)}
.dlbar .lb{margin-right:auto;font-size:11px;font-weight:300;color:var(--muted)}
.dlbtn{display:inline-flex;align-items:center;gap:7px;font:inherit;cursor:pointer;
  font-size:12px;font-weight:700;color:var(--ink-2);background:var(--panel);
  border:1px solid var(--hair);border-radius:8px;padding:8px 13px;
  transition:border-color var(--dur-fast) var(--ease),color var(--dur-fast) var(--ease),background var(--dur-fast) var(--ease),transform var(--dur-fast) var(--ease)}
.dlbtn:hover{border-color:var(--green);color:var(--green);transform:translateY(-1px)}
.dlbtn svg{width:14px;height:14px;flex:none}
.dlbtn .ext{font-size:10px;font-weight:900;letter-spacing:.03em;
  padding:2px 5px;border-radius:4px;background:var(--tint);color:var(--muted)}
.dlbtn:hover .ext{background:var(--green-tint);color:var(--green)}

.arch{margin-top:14px}
.arch-hd{display:flex;align-items:center;gap:12px;margin-bottom:4px}
.arch-hd .t{font-size:12px;font-weight:700;color:var(--ink-2)}
.arch-hd .s{font-size:11px;font-weight:300;color:var(--muted)}
.rlist{margin-top:10px;display:grid;grid-template-columns:repeat(2,1fr);gap:12px}
.ritem{display:block;background:var(--panel);border:1px solid var(--hair);border-radius:12px;
  padding:16px 17px;cursor:pointer;
  transition:border-color var(--dur-fast) var(--ease),transform var(--dur-fast) var(--ease)}
.ritem:hover{border-color:var(--green);transform:translateY(-2px)}
.ritem .rhd{display:flex;align-items:baseline;gap:8px;margin-bottom:8px}
.ritem .rd{font-size:11px;font-weight:900;color:var(--green);letter-spacing:.02em}
.ritem .rk{font-size:10.5px;font-weight:300;color:var(--faint)}
.ritem .rt{font-size:13.5px;font-weight:700;line-height:1.45;letter-spacing:-.012em;margin-bottom:7px}
.ritem .rsum{font-size:11.5px;font-weight:300;color:var(--muted);line-height:1.7;margin-bottom:11px}
.ritem .rmeta{font-size:10.5px;font-weight:300;color:var(--faint)}
.ritem .rmeta .cf{display:inline-flex;align-items:center;gap:5px;margin-left:4px;
  font-weight:700;color:var(--conf-high)}
.ritem .rmeta .cf i{width:6px;height:6px;border-radius:50%;background:currentColor;flex:none}
.ritem .rmeta .cf.mid{color:var(--conf-mid)}
.ritem .rmeta .cf.low{color:var(--conf-low)}
.ritem .rdl{display:flex;gap:6px;flex-wrap:wrap;margin-top:11px;padding-top:11px;
  border-top:1px solid var(--hair-3)}
.ritem .rdl .dlbtn{padding:5px 11px;font-size:11px}
.ritem .rdl .dlbtn .ext{display:none}
.ritem.old{display:none}
.rlist.show-old .ritem.old{display:block}
.archtoggle{display:inline-flex;align-items:center;gap:8px;font:inherit;cursor:pointer;
  margin-top:16px;font-size:12px;font-weight:700;color:var(--ink-2);
  background:var(--tint);border:1px solid var(--hair);border-radius:8px;padding:9px 15px;
  transition:border-color var(--dur-fast) var(--ease),color var(--dur-fast) var(--ease)}
.archtoggle:hover{border-color:var(--green);color:var(--green)}
.archtoggle .cnt{font-size:11px;font-weight:900;color:var(--muted)}
.archtoggle .chev{transition:transform var(--dur-base) var(--ease)}
.archtoggle.open .chev{transform:rotate(180deg)}
.archtoggle.open{color:var(--green);border-color:var(--green)}

/* ---------- 카테고리 상세 ---------- */
.cd{padding:24px 0;border-bottom:1px solid var(--hair)}
.cd:first-child{padding-top:0}
.cd:last-child{border-bottom:0}
.cd .hd{display:flex;align-items:baseline;gap:12px;margin-bottom:11px}
.cd .nm{font-size:16px;font-weight:900;letter-spacing:-.02em}
.cd .rt{margin-left:auto;display:flex;align-items:baseline;gap:13px}
.cd .cnt{font-size:11.5px;font-weight:300;color:var(--muted)}
.cd .dl{font-size:11px;font-weight:700;color:var(--faint)}
.cd .dl.up{color:var(--green)}
.cd .pc{font-size:14px;font-weight:900;letter-spacing:-.01em}
.cd .pc.hi{color:var(--conf-high)}
.cd .pc.mid{color:var(--conf-mid)}
.cd .pc.low{color:var(--conf-low)}
.cd .trk{margin-bottom:14px}
.cd .tags{display:flex;gap:7px;flex-wrap:wrap;margin-bottom:12px}
.tag{font-size:11.5px;font-weight:500;color:var(--ink-2);padding:4px 11px;
  border:1px solid var(--hair);border-radius:20px}
.cd .top{font-size:12.5px;font-weight:300;color:var(--muted)}
.cd .top b{font-weight:700;color:var(--ink)}
.cd .top .cf{font-weight:700;color:var(--conf-high);background:var(--conf-high-tint);
  padding:2px 8px;border-radius:5px;white-space:nowrap}
.cd .top .cf.mid{color:var(--conf-mid);background:var(--conf-mid-tint)}
.cd .top .cf.low{color:var(--conf-low);background:var(--conf-low-tint)}

/* ---------- 위키 ---------- */
.wiki{display:grid;grid-template-columns:172px 1fr 208px;gap:38px;margin-top:6px}
.tree .g{font-size:9.5px;font-weight:700;letter-spacing:.13em;color:var(--faint);margin:18px 0 6px}
.tree .g:first-child{margin-top:0}
.tree a{display:block;font-size:12px;font-weight:400;color:var(--ink-2);padding:4px 0}
.tree a.on{font-weight:700;color:var(--ink);position:relative}
.tree a.on::before{content:"";position:absolute;left:-12px;top:6px;bottom:6px;
  width:2px;background:var(--green)}
.dmeta{display:flex;gap:24px;flex-wrap:wrap;padding-bottom:15px;
  border-bottom:1px solid var(--hair);font-size:10.5px;font-weight:300;color:var(--muted)}
.dmeta b{font-weight:500;color:var(--ink-2)}
.zone{font-size:9.5px;font-weight:700;letter-spacing:.14em;color:var(--faint);
  margin:30px 0 12px;padding-bottom:9px;border-bottom:1px solid var(--hair)}
.zone.hard{border-bottom-color:var(--ink)}
.doc p{font-size:13.5px;font-weight:400;color:var(--ink-2);line-height:1.85;margin-bottom:10px}
.fn{font-size:9px;font-weight:700;color:var(--green);vertical-align:super;margin-left:2px}
.tl .i{display:grid;grid-template-columns:64px 1fr;gap:16px;padding:15px 0;
  border-top:1px solid var(--hair);align-items:baseline}
.tl .i:first-child{border-top:0}
.tl .d{font-size:11px;font-weight:500;color:var(--muted)}
.tl .i.new .d{color:var(--ink);font-weight:900}
.tl .t{font-size:12.5px;font-weight:300;color:var(--muted);line-height:1.65}
.tl .t b{font-weight:700;color:var(--ink)}
.col h5{font-size:9.5px;font-weight:700;letter-spacing:.14em;color:var(--faint);
  padding-bottom:10px;border-bottom:1px solid var(--ink);
  display:flex;justify-content:space-between;align-items:baseline}
.col h5 .c{font-size:10.5px;font-weight:900;color:var(--ink-2);letter-spacing:0}
.col .it{padding:12px 0;border-bottom:1px solid var(--hair);
  font-size:11.5px;font-weight:300;color:var(--muted);line-height:1.55}
.col .it b{display:block;font-size:12.5px;font-weight:700;color:var(--ink);margin-bottom:1px}
.col .it .no{font-weight:900;color:var(--green);margin-right:7px}
.col + .col{margin-top:34px}

/* ---------- 에이전트 ---------- */
.chat{display:grid;grid-template-columns:1fr 236px;gap:38px;margin-top:6px}
.thread{display:flex;flex-direction:column;gap:26px;border-top:1px solid var(--ink)}
.turn.me{display:flex;flex-direction:column;align-items:flex-end;padding-top:26px;
  border-top:1px solid var(--hair)}
.turn.me:first-child{border-top:0;padding-top:22px}
.turn.me .msg{background:var(--hair-3);padding:11px 16px;border-radius:15px 15px 4px 15px;
  font-size:13px;font-weight:500;line-height:1.65;max-width:76%}
.turn.ai{display:grid;grid-template-columns:16px 1fr;gap:14px}
.mark{width:15px;height:15px;border:1.5px solid var(--ink);border-radius:3px;
  position:relative;margin-top:6px}
.mark::after{content:"";position:absolute;inset:3px;background:var(--green);border-radius:1px}
.who{font-size:9.5px;font-weight:700;letter-spacing:.14em;color:var(--faint);margin-bottom:7px}
.turn.ai p{font-size:13.5px;font-weight:400;line-height:1.9;margin-bottom:11px;max-width:620px}
.cites{display:flex;gap:7px;flex-wrap:wrap;margin-top:15px;padding-top:13px;
  border-top:1px solid var(--hair-3)}
.cite{display:inline-flex;align-items:center;gap:7px;font-size:10.5px;font-weight:500;
  color:var(--ink-2);border:1px solid var(--hair);border-radius:20px;padding:3px 11px}
.cite .n{font-size:9.5px;font-weight:900;color:var(--green)}
.cite.doc{border-color:var(--green);color:var(--green);font-weight:700}
.acts{display:flex;gap:17px;flex-wrap:wrap;margin-top:14px;
  font-size:11.5px;font-weight:500;color:var(--muted)}
.acts span:first-child{color:var(--green);font-weight:700}
.none{border-left:2px solid var(--hair);padding-left:15px}
.none h6{font-size:13px;font-weight:700;margin-bottom:6px}
.none p{font-size:12.5px;font-weight:300;color:var(--muted);line-height:1.75;max-width:500px}
.composer{position:sticky;bottom:14px;z-index:5;margin-top:32px;
  background:var(--panel);border:1px solid var(--hair);border-radius:13px;
  box-shadow:0 6px 22px rgba(20,20,20,.07);
  padding:12px 12px 12px 17px;display:flex;align-items:center;gap:14px}
.composer .ph2{flex:1;font-size:13px;font-weight:300;color:var(--faint)}
.composer .send{font-size:11px;font-weight:700;color:var(--panel);background:var(--ink);
  border-radius:18px;padding:6px 14px}
.hint{display:flex;gap:18px;flex-wrap:wrap;margin-top:10px;padding-left:2px;
  font-size:10.5px;font-weight:300;color:var(--faint)}
.ev{padding:15px 0;border-bottom:1px solid var(--hair)}
.ev .t{display:flex;gap:8px;align-items:baseline;margin-bottom:5px}
.ev .no{font-size:10px;font-weight:900;color:var(--green)}
.ev .src{font-size:10.5px;font-weight:500;color:var(--muted)}
.ev .src.doc{color:var(--green);font-weight:700}
.ev h6{font-size:12px;font-weight:700;line-height:1.45;margin-bottom:6px}
.ev .x{font-size:11px;font-weight:300;color:var(--muted);line-height:1.6;
  padding-left:10px;border-left:1px solid var(--hair)}
.ev .f{font-size:10px;font-weight:300;color:var(--faint);margin-top:7px}

@media (max-width:1020px){
  .app{grid-template-columns:1fr}
  .side{border-right:0;border-bottom:1px solid var(--hair)}
  .side a.on::before{display:none}
  .main{padding:26px 22px 60px}
  .split,.wiki,.chat{grid-template-columns:1fr;gap:28px}
  .split > div:first-child{padding-right:0;border-right:0}
  .kpi{grid-template-columns:repeat(2,1fr);gap:20px 0}
  .kpi > div{padding:0 20px}
  .row{grid-template-columns:120px 1fr;gap:18px}
  .row .meta{grid-column:2;text-align:left}
  .row .meta .idl{justify-content:flex-start}
  .rlist{grid-template-columns:1fr}
  .ag-seg{width:100%}
  .ag-seg button{flex:1;text-align:center}
  .mw-modal{width:min(560px,calc(100vw - 32px));padding:20px 18px 18px}
}

/* ================= 상단바 우측 — 환경설정/프로필 묶음 ================= */
/* TopBar.jsx(PC) — 로고 옆이 아니라 페이지 맨 우측 끝에 붙이는 컨테이너.
   자식(.gear/.avatar)의 개별 margin-left는 여기서 0으로 리셋하고 gap으로만 간격을 줍니다. */
.deck-right{margin-left:auto;display:flex;align-items:center;gap:10px}
.deck-right .gear,.deck-right .avatar{margin-left:0}

/* ================= 설정 버튼 / 패널 (다크모드) ================= */
.gear{
  margin-left:14px;width:30px;height:30px;border-radius:50%;flex:none;
  border:1px solid var(--hair);background:var(--panel);color:var(--ink-2);
  font-size:14px;cursor:pointer;display:flex;align-items:center;justify-content:center;
  transition:transform var(--dur-fast) var(--ease),border-color var(--dur-fast) var(--ease),color var(--dur-fast) var(--ease);
}
.gear:hover{border-color:var(--green);color:var(--green);transform:rotate(30deg)}
.gear.open{color:var(--green);border-color:var(--green)}
.settings-panel{
  position:fixed;top:60px;right:28px;z-index:80;
  background:var(--panel);border:1px solid var(--hair);border-radius:12px;
  box-shadow:0 16px 36px rgba(20,20,20,.16);width:252px;padding:16px;
  opacity:0;visibility:hidden;transform:translateY(-8px) scale(.98);
  transition:opacity var(--dur-base) var(--ease),transform var(--dur-base) var(--ease),visibility var(--dur-base);
}
.settings-panel.open{opacity:1;visibility:visible;transform:translateY(0) scale(1)}
.settings-panel h4{font-size:10px;font-weight:700;letter-spacing:.12em;color:var(--faint);margin-bottom:10px}
.settings-panel h4:not(:first-child){margin-top:16px;padding-top:14px;border-top:1px solid var(--hair-3)}
.sp-row{display:flex;align-items:center;justify-content:space-between;font-size:13px;font-weight:500;padding:8px 0}
.sp-row.sp-sub{font-size:10.5px;font-weight:300;color:var(--faint);padding-top:8px;margin-top:2px;border-top:1px solid var(--hair-3)}
.switch{width:38px;height:22px;border-radius:20px;background:var(--track);border:none;position:relative;cursor:pointer;flex:none;
  transition:background var(--dur-base) var(--ease)}
.switch i{position:absolute;top:2px;left:2px;width:18px;height:18px;border-radius:50%;background:#fff;
  box-shadow:0 1px 3px rgba(0,0,0,.25);transition:transform var(--dur-base) var(--ease)}
.switch[aria-checked="true"]{background:var(--green)}
.switch[aria-checked="true"] i{transform:translateX(16px)}

/* ================= 프로필 / 소셜 로그인 ================= */
.avatar{
  margin-left:10px;width:30px;height:30px;border-radius:50%;flex:none;padding:0;
  border:1px solid var(--hair);background:var(--panel);color:var(--ink-2);cursor:pointer;
  display:flex;align-items:center;justify-content:center;
  transition:border-color var(--dur-fast) var(--ease),color var(--dur-fast) var(--ease),background var(--dur-fast) var(--ease),transform var(--dur-fast) var(--ease);
}
.avatar:hover{border-color:var(--green);color:var(--green);transform:translateY(-1px)}
.avatar.open{border-color:var(--green)}
.avatar.auth{background:var(--green);border-color:var(--green);color:#fff}
.avatar .ini{font-size:11px;font-weight:700;line-height:1}
.avatar .ico{display:block}
.profile-panel{
  position:fixed;top:60px;right:28px;z-index:80;
  background:var(--panel);border:1px solid var(--hair);border-radius:12px;
  box-shadow:0 16px 36px rgba(20,20,20,.16);width:264px;padding:16px;
  opacity:0;visibility:hidden;transform:translateY(-8px) scale(.98);
  transition:opacity var(--dur-base) var(--ease),transform var(--dur-base) var(--ease),visibility var(--dur-base);
}
.profile-panel.open{opacity:1;visibility:visible;transform:translateY(0) scale(1)}
.pp-hd{margin-bottom:12px}
.pp-ttl{font-size:14px;font-weight:900;letter-spacing:-.01em}
.pp-sub{font-size:11px;font-weight:300;color:var(--muted);margin-top:2px}
.pp-oauth{
  display:flex;align-items:center;gap:10px;width:100%;text-align:left;font:inherit;cursor:pointer;
  border:1px solid var(--hair);background:var(--panel);border-radius:9px;padding:9px 12px;margin-top:8px;
  font-size:12.5px;font-weight:500;color:var(--ink);
  transition:border-color var(--dur-fast) var(--ease),background var(--dur-fast) var(--ease);
}
.pp-oauth:hover{border-color:var(--green);background:var(--green-tint)}
.pp-oauth .ic{width:20px;height:20px;border-radius:5px;flex:none;display:flex;
  align-items:center;justify-content:center;font-size:9.5px;font-weight:900;color:#fff}
.pp-oauth.google .ic{background:#4285F4}
.pp-oauth.github .ic{background:#181717}
.pp-oauth.kakao .ic{background:#FEE500;color:#3c1e1e}
.pp-note{font-size:10px;font-weight:300;color:var(--faint);margin-top:12px;
  padding-top:10px;border-top:1px solid var(--hair-3);line-height:1.6}
.pp-me{display:flex;align-items:center;gap:11px;padding-bottom:12px;border-bottom:1px solid var(--hair-2)}
.pp-av{width:38px;height:38px;border-radius:50%;flex:none;background:var(--green);color:#fff;
  font-size:15px;font-weight:700;display:flex;align-items:center;justify-content:center}
.pp-info{min-width:0}
.pp-name{font-size:13.5px;font-weight:700}
.pp-mail{font-size:11px;font-weight:300;color:var(--muted);margin-top:1px;
  overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.pp-ws{display:flex;align-items:center;justify-content:space-between;padding:11px 0;border-bottom:1px solid var(--hair-2)}
.pp-ws-lb{font-size:9.5px;font-weight:700;letter-spacing:.12em;color:var(--faint)}
.pp-ws-nm{font-size:12px;font-weight:700;color:var(--green)}
.pp-item{display:block;width:100%;text-align:left;border:0;background:none;font:inherit;cursor:pointer;
  font-size:12.5px;font-weight:500;color:var(--ink-2);padding:9px 8px;border-radius:7px;margin-top:4px;
  transition:background var(--dur-fast) var(--ease),color var(--dur-fast) var(--ease)}
.pp-item:first-of-type{margin-top:8px}
.pp-item:hover{background:var(--tint);color:var(--ink)}
.pp-item.danger{color:var(--amber)}
.pp-item.danger:hover{background:var(--green-tint)}

/* ================= 애니메이션 ================= */
@keyframes viewIn{from{opacity:0;transform:translateY(10px)} to{opacity:1;transform:translateY(0)}}
.view.on{animation:viewIn var(--dur-slow) var(--ease)}

.side a{transition:background var(--dur-fast) var(--ease),color var(--dur-fast) var(--ease),padding-left var(--dur-fast) var(--ease)}
.side a:not(.off):hover{padding-left:14px}
.side a.on::before{animation:railGrow var(--dur-base) var(--ease)}
@keyframes railGrow{from{transform:scaleY(0)} to{transform:scaleY(1)}}

@keyframes fadeUp{from{opacity:0;transform:translateY(6px)} to{opacity:1;transform:translateY(0)}}
.kpi > div{animation:fadeUp var(--dur-slow) var(--ease) both}
.kpi > div:nth-child(1){animation-delay:.02s}
.kpi > div:nth-child(2){animation-delay:.08s}
.kpi > div:nth-child(3){animation-delay:.14s}
.kpi > div:nth-child(4){animation-delay:.2s}

@keyframes drawLine{to{stroke-dashoffset:0}}
@keyframes fadeIn{to{opacity:1}}
.chart .line{stroke-dasharray:900;stroke-dashoffset:900;animation:drawLine 1.1s var(--ease) forwards .15s}
.chart .area{opacity:0;animation:fadeIn .6s var(--ease) forwards .55s}
.chart .dots circle,.chart .now-dot{opacity:0;animation:fadeIn .4s var(--ease) forwards .9s}

.trk i,.tr .bar i,.cd .trk i{transition:width .9s var(--ease)}
.row{transition:background var(--dur-fast) var(--ease)}
.row:hover{background:var(--tint)}
.cd{transition:background var(--dur-fast) var(--ease)}

.search{transition:box-shadow var(--dur-fast) var(--ease)}
.search:hover{box-shadow:0 0 0 3px var(--green-tint)}

.tag,.cite{transition:transform var(--dur-fast) var(--ease),border-color var(--dur-fast) var(--ease)}
.tag:hover,.cite:hover{transform:translateY(-1px);border-color:var(--green)}

.composer .send,.deck .gear,.go{transition:transform var(--dur-fast) var(--ease)}
.composer .send:hover,.go:hover{transform:translateY(-1px)}

@media (prefers-reduced-motion: reduce){
  *,*::before,*::after{animation-duration:.001ms !important;animation-iteration-count:1 !important;transition-duration:.001ms !important}
}

.sp-seg{display:flex;gap:3px;background:var(--hair-2);border-radius:8px;padding:3px}
.sp-seg button{appearance:none;border:0;background:none;font:inherit;cursor:pointer;
  font-size:11px;font-weight:500;color:var(--muted);padding:5px 10px;border-radius:6px;white-space:nowrap}
.sp-seg button.on{background:var(--panel);color:var(--ink);font-weight:700}
.settings-panel h4+.sp-row,.settings-panel .sp-row{gap:16px}

/* 설정 단독 페이지 */
.ph2{padding-bottom:16px;border-bottom:1px solid var(--ink);margin-bottom:8px;
  display:flex;align-items:baseline;gap:12px}
.ph2 h2{font-size:23px;font-weight:900;letter-spacing:-.03em}
.ph2 .dt{font-size:12px;font-weight:300;color:var(--muted)}
.set-lb{font-size:9.5px;font-weight:700;letter-spacing:.14em;color:var(--faint);margin:26px 0 10px}
.set-card{border:1px solid var(--hair);border-radius:12px;overflow:hidden;background:var(--panel);max-width:640px}
.set-row{display:flex;align-items:center;gap:18px;padding:16px 18px;border-top:1px solid var(--hair-2)}
.set-row:first-child{border-top:0}
.set-row .tx{flex:1;min-width:0}
.set-row .tx .nm{font-size:13.5px;font-weight:700}
.set-row .tx .ds{font-size:11.5px;font-weight:300;color:var(--muted);margin-top:2px;line-height:1.5}
.set-row .vl{font-size:12.5px;font-weight:500;color:var(--muted)}
.set-row .sp-seg{flex:none}
.set-ver{margin-top:24px;font-size:10.5px;font-weight:300;color:var(--faint)}

/* ---------- 설정 입력 필드 (기존 set-row 안에서 사용) ---------- */
.fld{font:inherit;font-size:12.5px;font-weight:500;color:var(--ink);background:var(--panel);
  border:1px solid var(--hair);border-radius:8px;padding:7px 11px;flex:none;
  transition:border-color var(--dur-fast) var(--ease),box-shadow var(--dur-fast) var(--ease)}
.fld:hover{border-color:var(--green)}
.fld:focus{outline:none;border-color:var(--green);box-shadow:0 0 0 3px var(--green-tint)}
select.fld,input[type="time"].fld{cursor:pointer}
input[type="text"].fld,input[type="email"].fld{min-width:196px}
.set-av{display:flex;align-items:center;gap:12px;flex:none}
.set-av .av{width:40px;height:40px;border-radius:50%;flex:none;background:var(--green);color:#fff;
  font-size:14px;font-weight:700;display:flex;align-items:center;justify-content:center}
:root[data-theme="dark"] .set-av .av{color:#0d1512}
.dlbtn.danger{color:var(--amber)}
.dlbtn.danger:hover{color:var(--amber);border-color:var(--amber)}

/* ---------- 에이전트: 팀 공유 / 내 에이전트 ---------- */
.ag-seg{width:max-content;margin:18px 0 2px}
.ag-seg button{font-size:12px;padding:7px 16px}
.ag-pane{display:none}
.ag-pane.on{display:grid}
.ag-list{display:flex;gap:7px;flex-wrap:wrap;align-items:center;
  margin-bottom:16px;padding-bottom:14px;border-bottom:1px solid var(--hair-3)}
.ag-list .lb{font-size:9.5px;font-weight:700;letter-spacing:.13em;color:var(--faint);margin-right:3px}
.ag-list .lb .own{color:var(--green)}
.ag-conv{font:inherit;cursor:pointer;background:var(--panel);border:1px solid var(--hair);
  border-radius:20px;padding:5px 12px;font-size:11.5px;font-weight:500;color:var(--ink-2);
  display:inline-flex;align-items:baseline;gap:8px;
  transition:border-color var(--dur-fast) var(--ease),color var(--dur-fast) var(--ease),background var(--dur-fast) var(--ease),transform var(--dur-fast) var(--ease)}
.ag-conv:hover{border-color:var(--green);color:var(--green);transform:translateY(-1px)}
.ag-conv.on{border-color:var(--green);background:var(--green-tint);color:var(--green);font-weight:700}
.ag-conv .d{font-size:10px;font-weight:300;color:var(--faint)}
.ag-conv.on .d{color:var(--green)}
.ag-conv.new{border-style:dashed;color:var(--muted)}

/* ---------- 모달 (계정 설정 · 리포트 상세) ---------- */
.mw-scrim{position:fixed;inset:0;z-index:150;background:rgba(16,20,22,.42);
  opacity:0;visibility:hidden;
  transition:opacity var(--dur-base) var(--ease),visibility var(--dur-base)}
.mw-scrim.open{opacity:1;visibility:visible}
.mw-modal{position:fixed;z-index:151;left:50%;top:50%;
  transform:translate(-50%,-46%) scale(.98);width:min(560px,calc(100vw - 40px));
  max-height:84vh;overflow-y:auto;background:var(--panel);
  border:1px solid var(--hair);border-radius:16px;box-shadow:0 20px 50px rgba(20,20,20,.18);
  padding:24px 26px 22px;opacity:0;visibility:hidden;
  transition:opacity var(--dur-base) var(--ease),transform var(--dur-base) var(--ease),visibility var(--dur-base)}
.mw-modal.open{opacity:1;visibility:visible;transform:translate(-50%,-50%) scale(1)}
.mw-hd{display:flex;align-items:flex-start;gap:14px;padding-bottom:14px;border-bottom:1px solid var(--ink)}
.mw-hd .eb{font-size:9.5px;font-weight:700;letter-spacing:.14em;color:var(--faint);margin-bottom:5px}
.mw-hd h3{font-size:18px;font-weight:900;letter-spacing:-.025em;line-height:1.32}
.mw-x{margin-left:auto;flex:none;width:28px;height:28px;border-radius:50%;cursor:pointer;
  border:1px solid var(--hair);background:var(--panel);color:var(--muted);font:inherit;font-size:12px;
  display:flex;align-items:center;justify-content:center;
  transition:border-color var(--dur-fast) var(--ease),color var(--dur-fast) var(--ease)}
.mw-x:hover{border-color:var(--green);color:var(--green)}
.mw-body .set-card{max-width:none}
.mw-lb{font-size:9.5px;font-weight:700;letter-spacing:.14em;color:var(--faint);margin:22px 0 10px}
.mw-vl{font-size:12.5px;font-weight:500;color:var(--ink-2)}
.mw-body .doc p:last-child{margin-bottom:0}
.mw-ft{display:flex;align-items:center;gap:8px;flex-wrap:wrap;
  margin-top:22px;padding-top:15px;border-top:1px solid var(--hair)}
.mw-ft .lb{margin-right:auto;font-size:11px;font-weight:300;color:var(--muted)}

/* ---------- 출처 원문 라우팅 링크 ---------- */
.row .meta a.s{cursor:pointer;transition:color var(--dur-fast) var(--ease)}
.row .meta a.s::after{content:"↗";font-size:9.5px;font-weight:700;margin-left:4px;color:var(--faint)}
.row .meta a.s:hover,.row .meta a.s:hover::after{color:var(--green)}
.row .meta a.w{cursor:pointer;transition:color var(--dur-fast) var(--ease)}
.row .meta a.w:hover{color:var(--green);font-weight:500}
a.cite{cursor:pointer}
a.cite .ex{font-size:9px;font-weight:700;color:var(--faint);margin-left:1px}
a.cite:hover{color:var(--green)}
a.cite:hover .ex{color:var(--green)}
.ev .lk{display:inline-flex;align-items:center;gap:4px;margin-top:9px;cursor:pointer;
  font-size:10.5px;font-weight:700;color:var(--green)}
.ev .lk:hover{text-decoration:underline}

/* ---------- 에이전트: 팀 공유 / 개인 구분 ---------- */
.ag-seg button .c{font-size:10px;font-weight:900;margin-left:6px;color:var(--faint)}
.ag-seg button.on .c{color:var(--green)}
.ag-ctx{display:flex;align-items:center;gap:12px;margin:16px 0 18px;padding:12px 15px;
  border:1px solid var(--hair);border-radius:12px;background:var(--tint)}
.ag-ctx.team{background:var(--green-tint);border-color:color-mix(in srgb,var(--green) 24%,transparent)}
.ag-ctx .ic{flex:none;font-size:9px;font-weight:900;letter-spacing:.12em;padding:5px 8px;border-radius:5px;
  background:var(--panel);color:var(--muted);border:1px solid var(--hair)}
.ag-ctx.team .ic{color:var(--green);border-color:color-mix(in srgb,var(--green) 30%,transparent)}
.ag-ctx .tx b{display:block;font-size:12.5px;font-weight:700;letter-spacing:-.01em}
.ag-ctx .tx span{font-size:11px;font-weight:300;color:var(--muted);line-height:1.5}
.ag-ctx .avs{margin-left:auto;flex:none;display:flex}
.ag-ctx .avs i{width:24px;height:24px;border-radius:50%;flex:none;font-style:normal;
  background:var(--green);color:#fff;font-size:9.5px;font-weight:700;
  display:flex;align-items:center;justify-content:center;
  border:2px solid var(--panel);margin-left:-8px}
.ag-ctx .avs i:first-child{margin-left:0}
.ag-ctx .avs i.more{background:var(--panel);color:var(--muted);border:1px solid var(--hair)}
:root[data-theme="dark"] .ag-ctx .avs i{color:#0d1512}
:root[data-theme="dark"] .ag-ctx .avs i.more{color:var(--muted)}
.ag-ctx .priv{margin-left:auto;flex:none;font-size:10.5px;font-weight:700;color:var(--muted);
  background:var(--panel);border:1px solid var(--hair);border-radius:20px;padding:4px 11px}
.turn.me .au{display:flex;align-items:center;gap:6px;margin-bottom:7px;
  font-size:10px;font-weight:700;letter-spacing:.05em;color:var(--muted)}
.turn.me .au i{width:17px;height:17px;border-radius:50%;font-style:normal;
  background:var(--green);color:#fff;font-size:8.5px;font-weight:700;
  display:flex;align-items:center;justify-content:center}
:root[data-theme="dark"] .turn.me .au i{color:#0d1512}
.who .fl{margin-left:8px;font-size:9px;font-weight:700;letter-spacing:.08em;
  padding:2px 7px;border-radius:4px;background:var(--green-tint);color:var(--green)}
.who .fl.priv{background:var(--tint);color:var(--muted)}
.ag-pane.mine .thread{border-top-color:var(--hair)}



/* ================= 온보딩: 사람확인 → 선호조사 → 대시보드 ================= */
.onboarding{position:fixed;inset:0;z-index:200;background:var(--tint);
  display:flex;align-items:center;justify-content:center;padding:28px 24px;overflow-y:auto;
  transition:opacity .45s var(--ease),visibility .45s}
.onboarding.done{opacity:0;visibility:hidden;pointer-events:none}
.ob-screen{display:none;width:100%;max-width:500px;margin:auto}
.ob-screen.on{display:block;animation:obIn .45s var(--ease)}
@keyframes obIn{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:none}}
.ob-card{background:var(--panel);border:1px solid var(--hair);border-radius:16px;
  box-shadow:0 20px 50px rgba(20,20,20,.10);padding:34px 32px}
.ob-logo{margin-bottom:22px}
.ob-eb{font-size:9.5px;font-weight:700;letter-spacing:.14em;color:var(--faint);text-transform:uppercase}
.ob-nm{font-size:24px;font-weight:900;letter-spacing:-.03em;color:var(--green);margin-top:3px}
.ob-h{font-size:19px;font-weight:900;letter-spacing:-.02em;margin-bottom:7px}
.ob-sub{font-size:12.5px;font-weight:300;color:var(--muted);line-height:1.7;margin-bottom:22px}
.ob-steps{display:flex;flex-wrap:wrap;gap:7px;margin-bottom:20px}
.ob-step{font-size:10.5px;font-weight:700;color:var(--faint);background:var(--tint);
  border:1px solid var(--hair);border-radius:20px;padding:5px 11px}
.ob-step.on{color:var(--green);background:var(--green-tint);border-color:color-mix(in srgb,var(--green) 30%,transparent)}
.ob-step.done{color:var(--conf-high);background:var(--conf-high-tint);border-color:color-mix(in srgb,var(--conf-high) 30%,transparent)}

/* 사람 확인 체크 */
.ob-check{display:flex;align-items:center;gap:13px;width:100%;text-align:left;font:inherit;cursor:pointer;
  background:var(--tint);border:1.5px solid var(--hair);border-radius:12px;padding:16px 16px;
  transition:border-color var(--dur-base) var(--ease),background var(--dur-base) var(--ease)}
.ob-check:hover{border-color:var(--green)}
.ob-check .box{flex:none;width:24px;height:24px;border-radius:6px;border:2px solid var(--faint);
  background:var(--panel);position:relative;transition:all var(--dur-base) var(--ease)}
.ob-check .box::after{content:"";position:absolute;left:7px;top:3px;width:6px;height:11px;
  border:solid #fff;border-width:0 2.5px 2.5px 0;transform:rotate(45deg) scale(0);
  transition:transform var(--dur-base) var(--ease)}
.ob-check .ob-check-l{font-size:14px;font-weight:700;color:var(--ink)}
.ob-check .ob-check-badge{margin-left:auto;font-size:9.5px;font-weight:700;letter-spacing:.06em;
  color:var(--muted);border:1px solid var(--hair);border-radius:5px;padding:3px 7px}
.ob-check.checking .box{border-color:var(--green);border-right-color:transparent;border-radius:50%;
  animation:obSpin .7s linear infinite}
@keyframes obSpin{to{transform:rotate(360deg)}}
.ob-check.checked{border-color:var(--conf-high);background:var(--conf-high-tint)}
.ob-check.checked .box{border-color:var(--conf-high);background:var(--conf-high)}
.ob-check.checked .box::after{transform:rotate(45deg) scale(1)}
.ob-gate-note{font-size:11.5px;font-weight:300;color:var(--muted);margin:16px 0 4px;min-height:16px}
.ob-gate-note.ok{color:var(--conf-high);font-weight:500}

/* 선호 조사 */
.ob-q{margin-bottom:20px}
.ob-q-t{font-size:12.5px;font-weight:700;color:var(--ink);margin-bottom:9px;display:flex;align-items:center;gap:8px}
.ob-q-s{font-size:10px;font-weight:700;color:var(--muted);background:var(--tint);
  border-radius:20px;padding:2px 8px}
.ob-chips{display:flex;flex-wrap:wrap;gap:8px}
.ob-chip{font-size:12px;font-weight:500;color:var(--ink-2);cursor:pointer;font-family:inherit;
  background:var(--panel);border:1px solid var(--hair);border-radius:20px;padding:7px 14px;
  transition:all var(--dur-fast) var(--ease)}
.ob-chip:hover{border-color:var(--green);color:var(--green)}
.ob-chip.sel{background:var(--green);border-color:var(--green);color:#fff;font-weight:700}
:root[data-theme="dark"] .ob-chip.sel{color:#0d1512}

.ob-actions{display:flex;align-items:center;gap:12px;margin-top:26px}
.ob-next{margin-left:auto;font:inherit;cursor:pointer;font-size:13.5px;font-weight:700;color:#fff;
  background:var(--green);border:0;border-radius:10px;padding:12px 22px;
  transition:transform var(--dur-fast) var(--ease),opacity var(--dur-fast) var(--ease)}
:root[data-theme="dark"] .ob-next{color:#0d1512}
.ob-next:hover:not(:disabled){transform:translateY(-1px)}
.ob-next:disabled{background:var(--hair);color:var(--faint);cursor:not-allowed}
:root[data-theme="dark"] .ob-next:disabled{color:var(--faint)}
.ob-skip{font:inherit;cursor:pointer;font-size:12.5px;font-weight:500;color:var(--muted);
  background:none;border:0;padding:8px 4px}
.ob-skip:hover{color:var(--ink)}
.ob-selnote{font-size:11px;font-weight:300;color:var(--muted)}
.ob-login .pp-oauth:first-of-type{margin-top:2px}
@media (max-width:520px){.ob-card{padding:26px 20px}}

/* 랜딩(시작 화면) — 온보딩 0단계 */
.ob-screen.ob-landing{max-width:760px}
.landing-inner{text-align:center}
.landing-brand{font-size:14px;font-weight:900;color:var(--green);letter-spacing:.04em;margin-bottom:18px}
.landing-inner h1{font-size:30px;font-weight:900;letter-spacing:-.03em;line-height:1.35;margin-bottom:14px}
.landing-sub{font-size:14px;color:var(--muted);font-weight:300;margin-bottom:40px}
.landing-features{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:44px;text-align:left}
.lf-card{border:1px solid var(--hair);border-radius:14px;padding:18px 16px;background:var(--panel)}
.lf-ic{font-size:22px;margin-bottom:10px}
.lf-t{font-size:13px;font-weight:700;margin-bottom:6px}
.lf-d{font-size:11.5px;color:var(--muted);font-weight:300;line-height:1.5}
.landing-cta{border:none;background:var(--green);color:#fff;font-size:14.5px;font-weight:700;
  padding:14px 36px;border-radius:26px;cursor:pointer;font-family:inherit;
  transition:transform var(--dur-fast) var(--ease),opacity var(--dur-fast) var(--ease)}
.landing-cta:hover{transform:translateY(-1px);opacity:.92}
@media (max-width:1020px){.landing-features{grid-template-columns:repeat(2,1fr)}}
@media (max-width:520px){.landing-inner h1{font-size:24px}}

/* 카테고리 현황 — 카드형(Progress Bar 제거, 뉴스 프리뷰 구성으로 개편) */
.cat-card-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:16px}
.cat-card-grid .cd{border:1px solid var(--hair);border-radius:16px;padding:20px;background:var(--panel);
  cursor:pointer;
  transition:border-color var(--dur-fast) var(--ease),transform var(--dur-fast) var(--ease),box-shadow var(--dur-fast) var(--ease)}
.cat-card-grid .cd:hover{border-color:var(--green);transform:translateY(-3px);box-shadow:0 16px 30px -16px rgba(21,23,26,.18)}
.cat-card-grid .cd .hd{display:flex;align-items:center;justify-content:space-between;margin-bottom:14px}
.cat-card-grid .cd .hd-count{font-size:11px;font-weight:500;color:var(--muted)}
.cat-card-grid .cd .hd-count b{font-size:13px;font-weight:900;color:var(--ink);margin-right:2px}
.cat-card-grid .cd .top-issue{font-size:17px;font-weight:700;letter-spacing:-.015em;margin-bottom:10px;line-height:1.42;color:var(--ink)}
.cat-card-grid .cd .tags{margin-bottom:14px}
.cat-card-grid .cd .cat-foot{display:flex;align-items:center;justify-content:space-between;gap:10px;
  padding-top:12px;border-top:1px dashed var(--hair-2)}

/* ---- 공용 컴포넌트: 카테고리 Badge / 인용문 Preview / 출처 버튼 / 원문 링크 / 신뢰도 Badge ---- */
.badge{display:inline-flex;align-items:center;gap:6px;font-size:11px;font-weight:700;padding:5px 10px;
  border-radius:8px;background:var(--green);color:#fff;border:1px solid var(--green)}
:root[data-theme="dark"] .badge{color:#0d1512}
.lvl{font-weight:700}
.lvl.hi{color:var(--conf-high)}
.lvl.mid{color:var(--conf-mid)}
.lvl.low{color:var(--conf-low)}

.quote{position:relative;background:var(--tint);border:1px solid var(--hair-2);border-radius:10px;
  padding:11px 13px 11px 30px;font-size:12px;line-height:1.62;color:var(--ink-2)}
.quote::before{content:'\275D';position:absolute;left:9px;top:5px;font-size:17px;font-weight:700;
  color:var(--faint);font-family:Georgia,'Noto Serif KR',serif}

.src-btn{display:inline;background:none;border:none;padding:0;margin:0;font:inherit;
  font-size:11.5px;font-weight:700;color:var(--ink-2);cursor:pointer}
.src-btn:hover{color:var(--green);text-decoration:underline;text-decoration-style:dotted;text-underline-offset:2px}

.ext-link{display:inline-flex;align-items:center;gap:4px;font-size:10.5px;font-weight:700;color:var(--muted);
  padding:4px 7px;border-radius:6px;flex:none}
.ext-link:hover{color:var(--green);background:var(--green-tint)}
.ext-link svg{width:9px;height:9px;flex:none}

.trust{display:inline-flex;align-items:center;gap:4px;font-size:11.5px;font-weight:800;
  white-space:nowrap;flex:none}
.trust svg{width:9px;height:9px;flex:none}
.trust.hi{color:var(--conf-high)}
.trust.mid{color:var(--conf-mid)}
.trust.low{color:var(--conf-low)}

/* 카테고리 관련 뉴스 모달 행 */
#catNewsRows{max-height:min(56vh,440px);overflow-y:auto;padding-right:4px}
.cat-news-item{padding:14px 0;border-bottom:1px solid var(--hair)}
.cat-news-item:last-child{border-bottom:0}
.cat-news-item h4{font-size:14px;font-weight:700;color:var(--ink);margin-bottom:5px;letter-spacing:-.01em}
.cat-news-item p{font-size:12px;font-weight:300;color:var(--muted);line-height:1.55;margin-bottom:8px}
.cat-news-item .meta{display:flex;align-items:center;gap:8px;font-size:11px;color:var(--muted)}
.cat-news-item .meta a.s{font-weight:700;color:var(--ink-2);cursor:pointer;text-decoration:none}
.cat-news-item .meta a.s:hover{color:var(--green)}

/* 위키 좌측 트리 · 연결된 문서 클릭 */
.tree a{cursor:pointer;transition:color var(--dur-fast) var(--ease)}
.tree a:hover{color:var(--green)}
.col button.it{display:block;width:100%;text-align:left;font:inherit;cursor:pointer;
  background:none;border:0;border-bottom:1px solid var(--hair);
  font-size:11.5px;font-weight:300;color:var(--muted);line-height:1.55;padding:12px 0;
  transition:color var(--dur-fast) var(--ease)}
.col button.it b{display:block;font-size:12.5px;font-weight:700;color:var(--ink);margin-bottom:1px;
  transition:color var(--dur-fast) var(--ease)}
.col button.it:hover,.col button.it:hover b{color:var(--green)}

/* 위키 근거 출처 → 원문 라우팅 링크 */
.col a.it{display:block;cursor:pointer;
  transition:color var(--dur-fast) var(--ease),border-color var(--dur-fast) var(--ease)}
.col a.it::after{content:"\2197";font-size:9px;font-weight:700;color:var(--faint);margin-left:5px}
.col a.it:hover{color:var(--green)}
.col a.it:hover::after{color:var(--green)}
.col a.it:hover b{color:var(--green)}
a.fn{cursor:pointer;text-decoration:none}
a.fn:hover{text-decoration:underline}

/* 에이전트 입력창(실제 입력 가능) */
.composer input.ph2{flex:1;min-width:0;font:inherit;font-size:13px;font-weight:400;color:var(--ink);
  background:none;border:none;outline:none;padding:0}
.composer input.ph2::placeholder{color:var(--faint);font-weight:300}
.composer button.send{font:inherit;border:none;cursor:pointer;font-size:11px;font-weight:700;
  color:var(--panel);background:var(--ink);border-radius:18px;padding:6px 14px;flex:none;
  transition:opacity var(--dur-fast) var(--ease),transform var(--dur-fast) var(--ease)}
.composer button.send:hover{opacity:.88;transform:translateY(-1px)}
.thread .empty-conv{padding:26px 0;font-size:12.5px;font-weight:300;color:var(--muted);line-height:1.8}

@media (max-width:1020px){.cat-card-grid{grid-template-columns:1fr}}

/* ---------- 대시보드 최신 뉴스(상단 고정) ---------- */
.news-feed{margin-bottom:6px}
.news-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:14px}
.news-card{border:1px solid var(--hair);border-radius:16px;padding:16px 18px;background:var(--panel);
  transition:border-color var(--dur-fast) var(--ease),transform var(--dur-fast) var(--ease),box-shadow var(--dur-fast) var(--ease)}
.news-card:hover{border-color:var(--green);transform:translateY(-3px);box-shadow:0 16px 30px -16px rgba(21,23,26,.18)}
.news-card.hidden{display:none}
.news-card .card-top{display:flex;align-items:flex-start;justify-content:space-between;gap:8px;margin-bottom:10px}
.news-card h4{font-size:14.5px;font-weight:700;line-height:1.46;letter-spacing:-.01em;margin:0 0 10px}
.news-card .quote{margin-bottom:10px}
.news-card .tags{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:10px}
.news-card .card-foot{display:flex;align-items:baseline;gap:0;
  padding-top:10px;border-top:1px dashed var(--hair-2)}
.news-card .time{font-size:11.5px;color:var(--muted);font-weight:300;white-space:nowrap}
.news-more{display:block;margin:14px auto 0;padding:9px 22px;border-radius:20px;
  border:1px solid var(--hair);background:var(--panel);color:var(--ink-2);
  font-size:12px;font-weight:700;cursor:pointer;font-family:inherit;
  transition:border-color var(--dur-fast) var(--ease),color var(--dur-fast) var(--ease)}
.news-more:hover{border-color:var(--green);color:var(--green)}
@media (max-width:1020px){.news-grid{grid-template-columns:repeat(2,1fr)}}
@media (max-width:720px){.news-grid{grid-template-columns:1fr}}

/* ---------- 간단 footer ---------- */
.site-footer{padding:26px 30px 34px;border-top:1px solid var(--hair);
  display:flex;justify-content:center;align-items:center;gap:8px;
  font-size:11.5px;color:var(--muted)}
.site-footer .ft-brand{font-weight:900;color:var(--ink)}

/* ============================================================= */
/* ===============  MOBILE 전용 레이아웃 (추가분)  =============== */
/* 769px 이상은 기존 PC 시안 그대로. 아래는 360~768px에서만 활성 */
/* 기존 디자인 토큰(--green,--panel,--hair,--muted 등)만 재사용 */
/* ============================================================= */

/* 모바일 전용 컴포넌트는 기본적으로 숨김 → 데스크탑 영향 0 */
.m-topbar,.m-tabbar,.m-drawer-scrim,.m-drawer,.m-sheet-scrim,.m-sheet{display:none}

@media (max-width:768px){
  /* 데스크탑 크롬 숨김 */
  .deck{display:none !important}
  .side{display:none !important}
  .app{grid-template-columns:1fr}

  /* 고정 상단바 + 하단 탭바 + Safe Area 만큼 여백 확보 */
  .main{
    max-width:none;
    padding:calc(52px + env(safe-area-inset-top) + 16px) 16px
            calc(66px + env(safe-area-inset-bottom) + 18px);
  }

  /* 카드 세로 1열 */
  .news-grid{grid-template-columns:1fr !important}

  /* 에이전트: 입력창을 탭바 위에 sticky 고정 (기존 UI 유지) */
  #v-agent .composer{bottom:calc(64px + env(safe-area-inset-bottom) + 12px)}

  /* ---------- 상단 고정바 ---------- */
  .m-topbar{
    display:flex;align-items:center;
    position:fixed;top:0;left:0;right:0;z-index:95;
    height:calc(52px + env(safe-area-inset-top));
    padding:env(safe-area-inset-top) 8px 0;
    background:var(--panel);border-bottom:1px solid var(--hair)
  }
  .m-icobtn{
    width:40px;height:40px;flex:none;border:0;background:transparent;
    color:var(--ink-2);border-radius:10px;cursor:pointer;
    display:flex;align-items:center;justify-content:center;
    transition:background var(--dur-fast) var(--ease),transform var(--dur-fast) var(--ease)
  }
  .m-icobtn:active{background:var(--tint);transform:scale(.92)}
  .m-topbar .m-logo{
    position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);
    padding-top:env(safe-area-inset-top);
    display:flex;align-items:center;gap:6px;
    font-size:17px;font-weight:900;letter-spacing:-.02em;color:var(--ink)
  }
  .m-topbar .m-logo .logo-mark{height:18px;width:18px}
  .m-topbar .m-right{margin-left:auto}
  .m-topbar .m-right .m-dot{
    position:absolute;top:9px;right:9px;width:6px;height:6px;border-radius:50%;
    background:var(--green);border:1.5px solid var(--panel)
  }
  .m-right{position:relative}

  /* ---------- 하단 고정 탭바 ---------- */
  .m-tabbar{
    display:grid;grid-template-columns:repeat(5,1fr);
    position:fixed;left:0;right:0;bottom:0;z-index:95;
    background:var(--panel);border-top:1px solid var(--hair);
    padding-bottom:env(safe-area-inset-bottom)
  }
  .mtab{
    appearance:none;border:0;background:transparent;cursor:pointer;
    display:flex;flex-direction:column;align-items:center;gap:3px;
    padding:8px 0 7px;color:var(--muted);font-size:10px;font-weight:500;
    letter-spacing:-.01em;position:relative;
    transition:color var(--dur-fast) var(--ease),transform var(--dur-fast) var(--ease)
  }
  .mtab .ic{width:23px;height:23px;display:block}
  .mtab .ic svg{width:23px;height:23px;stroke:currentColor;fill:none;
    stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round}
  .mtab:active{transform:scale(.9)}
  .mtab.active{color:var(--green);font-weight:700}
  .mtab.active::before{
    content:"";position:absolute;top:0;left:50%;transform:translateX(-50%);
    width:26px;height:2px;border-radius:2px;background:var(--green)
  }

  /* ---------- 좌측 Drawer ---------- */
  .m-drawer-scrim{
    display:block;position:fixed;inset:0;z-index:190;
    background:rgba(16,20,22,.42);opacity:0;visibility:hidden;
    transition:opacity var(--dur-base) var(--ease),visibility var(--dur-base)
  }
  .m-drawer-scrim.open{opacity:1;visibility:visible}
  .m-drawer{
    display:flex;flex-direction:column;
    position:fixed;top:0;bottom:0;left:0;z-index:191;
    width:min(80vw,300px);
    background:var(--rail);border-right:1px solid var(--hair);
    padding:calc(env(safe-area-inset-top) + 24px) 18px
            calc(env(safe-area-inset-bottom) + 22px);
    transform:translateX(-100%);
    transition:transform var(--dur-base) var(--ease)
  }
  .m-drawer.open{transform:none}
  .m-drawer .brand .eb{font-size:9.5px;font-weight:300;letter-spacing:.1em;color:var(--faint)}
  .m-drawer .brand .nm{font-size:19px;font-weight:900;letter-spacing:-.02em;margin-top:3px}
  .m-drawer .brand .rule{width:19px;height:2px;background:var(--green);margin:10px 0 4px}
  .m-drawer nav{margin-top:22px;display:flex;flex-direction:column;gap:2px}
  .m-drawer .lb{font-size:9.5px;font-weight:700;letter-spacing:.13em;color:var(--faint);
    padding:0 12px;margin:16px 0 6px}
  .m-drawer a{
    font-size:14.5px;font-weight:400;color:var(--ink-2);
    padding:11px 12px;border-radius:8px;cursor:pointer;
    display:flex;align-items:center;gap:11px;
    transition:background var(--dur-fast) var(--ease),color var(--dur-fast) var(--ease)
  }
  .m-drawer a .ic svg{width:19px;height:19px;stroke:currentColor;fill:none;
    stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round}
  .m-drawer a:active,.m-drawer a.on{background:#eceee9;color:var(--ink);font-weight:700}
  :root[data-theme="dark"] .m-drawer a:active,
  :root[data-theme="dark"] .m-drawer a.on{background:var(--tint)}
  .m-drawer .m-drawer-foot{
    margin-top:auto;padding-top:18px;border-top:1px solid var(--hair);
    font-size:10.5px;font-weight:300;color:var(--faint);line-height:1.9
  }

  /* ---------- 더보기 바텀시트 ---------- */
  .m-sheet-scrim{
    display:block;position:fixed;inset:0;z-index:190;
    background:rgba(16,20,22,.42);opacity:0;visibility:hidden;
    transition:opacity var(--dur-base) var(--ease),visibility var(--dur-base)
  }
  .m-sheet-scrim.open{opacity:1;visibility:visible}
  .m-sheet{
    display:block;position:fixed;left:0;right:0;bottom:0;z-index:191;
    background:var(--panel);border-top:1px solid var(--hair);
    border-radius:18px 18px 0 0;box-shadow:0 -12px 34px rgba(16,20,22,.16);
    padding:10px 14px calc(env(safe-area-inset-bottom) + 16px);
    transform:translateY(102%);
    transition:transform var(--dur-base) var(--ease)
  }
  .m-sheet.open{transform:none}
  .m-sheet .m-grip{width:38px;height:4px;border-radius:4px;background:var(--hair);
    margin:4px auto 12px}
  .m-sheet .m-sheet-h{font-size:9.5px;font-weight:700;letter-spacing:.13em;
    color:var(--faint);padding:0 6px 8px}
  .m-sheet button.m-sheet-item{
    appearance:none;width:100%;border:0;background:transparent;cursor:pointer;
    font:inherit;text-align:left;color:var(--ink);font-size:14.5px;font-weight:500;
    padding:14px 8px;border-top:1px solid var(--hair-3);
    display:flex;align-items:center;gap:12px;
    transition:background var(--dur-fast) var(--ease)
  }
  .m-sheet button.m-sheet-item:first-of-type{border-top:0}
  .m-sheet button.m-sheet-item:active{background:var(--tint)}
  .m-sheet button.m-sheet-item .ic svg{width:19px;height:19px;stroke:currentColor;
    fill:none;stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round}
  .m-sheet button.m-sheet-item.danger{color:var(--amber)}
  .m-sheet button.m-sheet-item .m-sub{margin-left:auto;font-size:11px;font-weight:300;color:var(--faint)}

  /* ---------- 모바일 카드형 배경 디자인 ---------- */
  body{background:#f1f2ee}
  :root[data-theme="dark"] body{background:#0f1113}
  .main{background:transparent}

  .ph{
    background:var(--panel);border:1px solid var(--hair);border-radius:16px;
    padding:16px 18px;margin-bottom:14px;
    border-bottom:1px solid var(--hair) !important
  }
  .pipe{
    background:var(--panel);border:1px solid var(--hair);border-radius:16px;
    padding:14px 16px;margin:0 0 14px;
    border-top:0 !important;border-bottom:0 !important
  }
  .search{
    background:var(--panel);border:1.5px solid var(--hair);border-radius:16px;margin-bottom:14px
  }
  .sec{
    background:var(--panel);border:1px solid var(--hair);border-radius:16px;
    padding:18px;margin-bottom:14px;border-bottom:0 !important
  }
  .sec:last-child{margin-bottom:0}

  /* KPI: 2x2 카드형 */
  .kpi{grid-template-columns:repeat(2,1fr);gap:12px}
  .kpi > div{
    background:var(--tint);border:1px solid var(--hair);border-radius:12px;
    padding:14px !important
  }
  .kpi > div + div{border-left:0 !important}

  /* ---------- 위키 / 에이전트: 리포트와 동일한 흰색 카드형 배경 ---------- */
  .wiki{gap:14px}
  .wiki > .tree,
  .wiki > .doc,
  .wiki > div:last-child{
    background:var(--panel);border:1px solid var(--hair);border-radius:16px;
    padding:18px;margin:0
  }
  .wiki > .tree{padding:14px 18px}

  .chat{gap:14px}
  .thread{
    background:var(--panel);border:1px solid var(--hair);border-radius:16px;
    padding:18px 18px 4px;border-top:0 !important
  }
  .turn.me:first-child{padding-top:0}
  .chat > .col{
    background:var(--panel);border:1px solid var(--hair);border-radius:16px;
    padding:18px;margin-top:14px
  }
  .hint{padding-left:0}

  /* 에이전트 탭 · 대화 목록 · 리포트 카드 */
  .ag-seg{width:100%;margin:0 0 14px}
  .ag-seg button{flex:1;text-align:center}
  .ag-list{background:var(--panel);border:1px solid var(--hair);border-radius:16px;
    padding:14px 16px;margin:0 0 14px;border-bottom:0}
  .ag-ctx{margin:0 0 14px;border-radius:16px;padding:14px 16px}
  .ag-ctx .avs i{width:22px;height:22px}
  .rlist{grid-template-columns:1fr}
  .mw-modal{padding:20px 18px 18px}
}

/* ================================================================= */
/* ==================  반응형 기준 (단일 파일)  ===================== */
/* 1021px 이상 : 기존 PC 시안 (deck 헤더 + 좌측 사이드바)             */
/* 769~1020px  : PC 레이아웃 1열 축소                                */
/* 768px 이하  : 모바일 UI (상단바 · 드로어 · 바텀시트 · 탭바)         */
/* ================================================================= */

/* ================================================================= */
/* =========  컴포넌트 분리 과정에서 필요해진 스타일 (신규만)  ========= */
/* 기존 클래스 값은 건드리지 않았고, 시안에 없던 클래스만 추가합니다.  */
/* ================================================================= */

/* Card.jsx — 범용 흰 카드 틀. 시안에 "어디서나 쓰는 카드" 클래스가 없어
   .set-card 와 동일한 값으로 새로 만들었습니다(.cd 는 카테고리 카드 전용이라 재사용 불가). */
.panel-card{border:1px solid var(--hair);border-radius:12px;overflow:hidden;background:var(--panel)}

/* TopBar.jsx (PC) — 시안 .deck 의 h1 과 같은 값 + 로고 아이콘(LogoMark). */
.deck .brand2{display:flex;align-items:center;gap:6px;
  font-size:13px;font-weight:900;letter-spacing:.01em;color:var(--ink)}
.deck .brand2 .logo-mark{height:17px;width:17px}

/* ---------- 위키: 좌측 문서 목록 · 연결된 문서 클릭 ---------- */
.tree a{cursor:pointer;transition:color var(--dur-fast) var(--ease)}
.tree a:hover{color:var(--green)}
.col a.it{display:block;cursor:pointer;transition:color var(--dur-fast) var(--ease)}
.col a.it::after{content:"\2197";font-size:9px;font-weight:700;color:var(--faint);margin-left:5px}
.col a.it:hover,.col a.it:hover::after{color:var(--green)}
.col button.it{display:block;width:100%;text-align:left;font:inherit;cursor:pointer;
  background:none;border:0;border-bottom:1px solid var(--hair);
  font-size:11.5px;font-weight:300;color:var(--muted);line-height:1.55;padding:12px 0;
  transition:color var(--dur-fast) var(--ease)}
.col button.it b{display:block;font-size:12.5px;font-weight:700;color:var(--ink);margin-bottom:1px;
  transition:color var(--dur-fast) var(--ease)}
.col button.it:hover,.col button.it:hover b{color:var(--green)}
a.fn{cursor:pointer;text-decoration:none}
a.fn:hover{text-decoration:underline}

/* ---------- 에이전트: 실제 입력 가능한 입력창 ---------- */
.composer input.ph2{flex:1;min-width:0;font:inherit;font-size:13px;font-weight:400;color:var(--ink);
  background:none;border:none;outline:none;padding:0}
.composer input.ph2::placeholder{color:var(--faint);font-weight:300}
.composer button.send{font:inherit;border:none;cursor:pointer;font-size:11px;font-weight:700;
  color:var(--panel);background:var(--ink);border-radius:18px;padding:6px 14px;flex:none;
  transition:opacity var(--dur-fast) var(--ease),transform var(--dur-fast) var(--ease)}
.composer button.send:hover{opacity:.88;transform:translateY(-1px)}
.thread .empty-conv{padding:26px 0;font-size:12.5px;font-weight:300;color:var(--muted);line-height:1.8}

/* ---------- 일일 리포트: 분류 카운트 줄 · 오늘의 키워드 줄 ---------- */
.rep-cats{display:flex;gap:20px;flex-wrap:wrap;padding-bottom:12px;
  border-bottom:1px solid var(--hair);font-size:12px;color:var(--muted)}
.rep-cats .all{font-weight:700;color:var(--ink)}
.rep-cats b{font-weight:300;color:var(--faint)}
.rep-cats .all b{font-weight:300;color:var(--muted)}
.rep-kw{display:flex;gap:16px;flex-wrap:wrap;margin-top:13px;
  font-size:11.5px;font-weight:500;color:var(--ink-2)}
.rep-kw .lb{color:var(--faint);letter-spacing:.06em;font-size:10px;font-weight:700}

/* 보관함 카드의 신뢰도 배지 — 기본(높음) 색만 지정돼 있어 보완 */
.ritem .rmeta .cf{color:var(--conf-high)}

/* ══════════════════════════════════════════════════════════════════
   2026.08 수정사항 반영분 — 기존 클래스 값은 하나도 건드리지 않고 뒤에만 추가
   (1) 온보딩 관심사 화면  (2) 로고 버튼  (3) 대시보드 필터 바
   (4) 위키 키워드 연동    (5) 리포트 다운로드  (6) 카테고리 원그래프
   ══════════════════════════════════════════════════════════════════ */

/* ── (1) 첫 진입: 관심사 선택 화면 ───────────────────────────────── */
.ob-stage{min-height:100vh;display:flex;align-items:center;justify-content:center;
  padding:40px 20px;background:var(--tint)}
.ob-screen .ob-card{width:100%}
.ob-actions .ob-selnote{margin-left:0}
.ob-actions .ob-next{margin-left:auto}

/* ── (2) 로고 = 새로고침 버튼 ────────────────────────────────────── */
/* ⚠ PC 레이아웃 버그 수정: .app이 `grid-template-columns:216px 1fr` 2열인데
   자식이 .deck(상단바) / .side(사이드바) / .main(본문) 3개라서
   .deck가 1열, .side가 2열, .main이 다음 줄로 밀려 레이아웃이 깨져 있었습니다.
   .deck를 전체 폭 헤더 행으로 고정합니다. (모바일에서는 .deck가 display:none이라 영향 없음) */
.app{grid-template-rows:auto 1fr}
.app > .deck{grid-column:1 / -1}
.deck .brand2,.m-topbar button.m-logo{font:inherit;background:none;border:0;padding:0;
  cursor:pointer;color:inherit;transition:opacity var(--dur-fast) var(--ease)}
.deck .brand2:hover,.m-topbar button.m-logo:hover{opacity:.65}
.brand.brand-btn{cursor:pointer;border-radius:8px;transition:opacity var(--dur-fast) var(--ease)}
.brand.brand-btn:hover{opacity:.7}

/* ── (3) 대시보드 뉴스 필터 바 (검색창 제거 후 대체) ───────────────── */
.feed-filter{display:flex;align-items:center;flex-wrap:wrap;gap:8px;margin-bottom:16px;
  padding:10px 14px;background:var(--green-tint);border-radius:10px}
.feed-filter .lb{font-size:9.5px;font-weight:700;letter-spacing:.12em;color:var(--green);
  text-transform:uppercase}
.feed-filter .chip{font-size:11.5px;font-weight:700;color:#fff;background:var(--green);
  border-radius:99px;padding:3px 10px}
.feed-filter .clr{margin-left:auto;font:inherit;font-size:11.5px;font-weight:700;
  color:var(--green);background:none;border:0;cursor:pointer;padding:2px 4px}
.feed-filter .clr:hover{text-decoration:underline}
.feed-empty{grid-column:1/-1;padding:26px 0;text-align:center;font-size:12.5px;
  font-weight:300;color:var(--muted)}
.kwrow.on{background:var(--green-tint);border-radius:8px}
.kwrow.on .h{color:var(--green)}

/* ── (4) 위키 본문 키워드 → 공시 원문 / 뉴스기사 연동 ─────────────── */
.wiki-kw{font:inherit;background:none;border:0;padding:0 1px;cursor:pointer;
  color:var(--green);font-weight:700;
  border-bottom:1px dashed color-mix(in srgb,var(--green) 45%,transparent);
  transition:background var(--dur-fast) var(--ease)}
.wiki-kw:hover{background:var(--green-tint);border-bottom-style:solid}
.kw-bar{display:flex;align-items:center;flex-wrap:wrap;gap:7px;margin:0 0 22px;
  padding:11px 13px;background:var(--tint);border:1px solid var(--hair);border-radius:10px}
.kw-bar .lb{font-size:9.5px;font-weight:700;letter-spacing:.12em;color:var(--faint);
  text-transform:uppercase;margin-right:3px}
.kw-chip{font:inherit;font-size:11.5px;font-weight:700;color:var(--green);cursor:pointer;
  background:var(--panel);border:1px solid var(--hair);border-radius:99px;padding:4px 10px;
  display:inline-flex;align-items:center;gap:4px;transition:all var(--dur-fast) var(--ease)}
.kw-chip:hover{border-color:var(--green);background:var(--green-tint)}
.kw-chip .ex{font-size:9.5px;opacity:.7}
.kwm-desc{font-size:12.5px;font-weight:300;line-height:1.75;color:var(--ink-2);margin-bottom:20px}
.kwm-list{margin-bottom:20px}
.kwm-item{display:flex;align-items:flex-start;gap:11px;padding:11px 12px;border-radius:10px;
  border:1px solid var(--hair);margin-bottom:7px;text-decoration:none;
  transition:all var(--dur-fast) var(--ease)}
.kwm-item:hover{border-color:var(--green);background:var(--green-tint);transform:translateX(2px)}
.kwm-item .ic{flex:none;width:16px;height:16px;color:var(--muted);margin-top:2px}
.kwm-item .ic svg{width:100%;height:100%}
.kwm-item.doc .ic{color:var(--green)}
.kwm-item .tx{display:flex;flex-direction:column;gap:4px;min-width:0}
.kwm-item .tx b{font-size:12.5px;font-weight:700;color:var(--ink);line-height:1.5}
.kwm-item .tx .s{font-size:10.5px;font-weight:300;color:var(--muted)}
.kwm-empty{font-size:11.5px;font-weight:300;color:var(--muted);padding:8px 2px;line-height:1.6}

/* ── (5) 리포트 다운로드 (주요 이슈 섹션 안) ────────────────────── */
.dlbar.tight{margin-bottom:18px}
.dl-toast{position:fixed;left:50%;bottom:32px;transform:translateX(-50%);z-index:120;
  background:var(--ink);color:#fff;font-size:12.5px;font-weight:500;
  padding:11px 18px;border-radius:99px;box-shadow:0 8px 26px rgba(0,0,0,.22);
  animation:fadeUp var(--dur-base) var(--ease)}
@media (max-width:768px){.dl-toast{bottom:78px;font-size:11.5px;max-width:88vw;text-align:center}}

/* ── (6) 카테고리 현황 — 키워드 원그래프 ─────────────────────────── */
.pie-tabs{display:flex;flex-wrap:wrap;gap:7px;margin-bottom:20px}
.pie-tab{font:inherit;font-size:11.5px;font-weight:500;color:var(--ink-2);cursor:pointer;
  background:var(--panel);border:1px solid var(--hair);border-radius:99px;padding:5px 13px;
  transition:all var(--dur-fast) var(--ease)}
.pie-tab:hover{border-color:var(--green);color:var(--green)}
.pie-tab.on{background:var(--green);border-color:var(--green);color:#fff;font-weight:700}
:root[data-theme="dark"] .pie-tab.on{color:#0d1512}
.pie-grid{display:grid;grid-template-columns:1fr 1fr;gap:26px}
.pie-box{border:1px solid var(--hair);border-radius:14px;padding:20px 18px;background:var(--panel)}
.pie-hd{display:flex;align-items:baseline;gap:9px;margin-bottom:16px;flex-wrap:wrap}
.pie-hd .t{font-size:12.5px;font-weight:900;letter-spacing:-.01em;color:var(--ink)}
.pie-hd .s{font-size:10.5px;font-weight:300;color:var(--muted)}
.pie{display:flex;align-items:center;gap:20px;flex-wrap:wrap}
.pie svg{width:168px;height:auto;flex:none}
.pie .sl{transition:opacity var(--dur-fast) var(--ease),transform var(--dur-fast) var(--ease);
  transform-origin:84px 84px}
.pie .sl.clickable{cursor:pointer}
.pie .sl.clickable:hover{opacity:.82}
.pie .sl.on{transform:scale(1.045)}
.pie text.pie-ct{text-anchor:middle;font-size:22px;font-weight:900;fill:var(--ink);
  letter-spacing:-.03em}
.pie text.pie-cl{text-anchor:middle;font-size:9px;font-weight:700;fill:var(--faint);
  letter-spacing:.06em}
.pie-legend{flex:1;min-width:150px;list-style:none;margin:0;padding:0}
.pie-legend li{display:flex;align-items:center;gap:9px;padding:5px 6px;border-radius:7px;
  font-size:11.5px;transition:background var(--dur-fast) var(--ease)}
.pie-legend li.clickable{cursor:pointer}
.pie-legend li.clickable:hover{background:var(--tint)}
.pie-legend li.on{background:var(--green-tint)}
.pie-legend .sw{flex:none;width:10px;height:10px;border-radius:3px}
.pie-legend .w{font-weight:500;color:var(--ink-2);min-width:0;overflow:hidden;
  text-overflow:ellipsis;white-space:nowrap}
.pie-legend .v{margin-left:auto;font-weight:700;color:var(--ink);font-size:11px}
.pie-legend .p{font-weight:300;color:var(--muted);font-size:10.5px;min-width:30px;text-align:right}
.pie-empty{font-size:12px;font-weight:300;color:var(--muted);padding:30px 0;text-align:center}
@media (max-width:1020px){
  .pie-grid{grid-template-columns:1fr;gap:18px}
}
@media (max-width:520px){
  .pie{gap:14px;justify-content:center}
  .pie svg{width:150px}
}


/* ── (5-1) 주요 이슈 — 이슈별 다운로드 + 전체 리포트 모달 ───────── */
/* 이슈 행 .meta 안 다운로드 버튼 (대시보드에서는 downloadFormats를 안 넘기므로 렌더링 자체가 안 됨) */
.row .meta .idl{display:flex;flex-wrap:wrap;justify-content:flex-end;gap:6px;
  margin-top:10px;padding-top:10px;border-top:1px solid var(--hair-3)}
.row .meta .idl .dlbtn{padding:5px 10px;font-size:10.5px}

/* 이슈 행 클릭 → 전체 리포트 모달 (대시보드에서는 이 클래스가 안 붙습니다) */
.row.clickable{cursor:pointer;border-radius:10px;
  transition:background var(--dur-fast) var(--ease)}
.row.clickable:hover{background:var(--tint)}
.row.clickable:focus-visible{outline:2px solid var(--green);outline-offset:2px}

/* 전체 리포트 모달 본문 — 카드 없이 이어지는 본문 텍스트 + 출처 */
.rdm{width:min(640px,calc(100vw - 40px))}
.rdm-meta{display:flex;flex-wrap:wrap;gap:12px;margin-top:14px;
  font-size:11px;font-weight:300;color:var(--faint)}
.rdm-overview{font-size:12.5px;font-weight:300;line-height:1.85;color:var(--ink-2);margin-top:14px}
.rdm-body{margin-top:18px;padding-top:15px;border-top:1px solid var(--hair)}
.rdm-p{font-size:12.5px;font-weight:300;line-height:1.9;color:var(--ink-2);margin-bottom:16px}
.rdm-p .ct{display:block;font-size:10px;font-weight:700;letter-spacing:.05em;
  color:var(--faint);margin-bottom:3px}
.rdm-p b{font-weight:700;color:var(--ink)}
.rdm-p.on b{color:var(--green)}
.rdm-p a{margin-left:8px;font-size:10.5px;font-weight:500;color:var(--muted);
  text-decoration:none;cursor:pointer;transition:color var(--dur-fast) var(--ease)}
.rdm-p a:hover{color:var(--green)}
.rdm-p a.s::after{content:"↗";font-size:9px;font-weight:700;margin-left:3px}
.rdm-p a.doc{color:var(--green);font-weight:700}
.rdm-p a.w::before{content:"위키 · ";color:var(--faint);font-weight:300}
.rdm-empty{font-size:12px;font-weight:300;color:var(--muted);padding:14px 2px;line-height:1.7}
/* ===== 리포트 개편 추가분 — globals.css 맨 아래에 붙여넣기 ===== */

/* 오늘 리포트 큰 카드 — 히스토리 카드(.ritem)를 그대로 쓰되 한 줄 전체를 차지합니다. */
.ritem.today {
  grid-column: 1 / -1;
  padding: 22px 24px;
}
.ritem.today .rt {
  font-size: 20px;
  line-height: 1.4;
  margin: 10px 0 8px;
}
.ritem.today .rsum {
  font-size: 15px;
}

/* 큰 카드의 다운로드 줄 — 확장자까지 함께 보여줍니다. */
.rdl.wide {
  margin-top: 16px;
  padding-top: 16px;
  gap: 10px;
  flex-wrap: wrap;
}
.rdl.wide .dlbtn {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 9px 14px;
}
.rdl.wide .dlbtn svg {
  width: 16px;
  height: 16px;
}
.rdl.wide .ext {
  opacity: .55;
  font-size: 12px;
}

/* 히스토리가 비었을 때 */
.rlist-empty {
  padding: 28px 4px;
  color: var(--muted, #8a8f8d);
  font-size: 14px;
}

/* 페이지 넘김 */
.rpage {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  margin-top: 20px;
}
.rpage-btn {
  min-width: 34px;
  height: 34px;
  padding: 0 9px;
  border: 1px solid var(--line, #e3e6e5);
  border-radius: 8px;
  background: transparent;
  color: inherit;
  font-size: 14px;
  cursor: pointer;
}
.rpage-btn:hover:not(:disabled) {
  border-color: var(--brand, #175243);
}
.rpage-btn.on {
  background: var(--brand, #175243);
  border-color: var(--brand, #175243);
  color: #fff;
  font-weight: 600;
}
.rpage-btn:disabled {
  opacity: .35;
  cursor: default;
}

/* 모바일에서는 히스토리를 1열로 */
@media (max-width: 760px) {
  .ritem.today {
    padding: 18px 16px;
  }
  .ritem.today .rt {
    font-size: 17px;
  }
  .rdl.wide .ext {
    display: none;
  }
}

/* 섹션 제목 키우기 — 오늘 리포트 / 리포트 히스토리 */
.sh.big .t {
  font-size: 20px;
  font-weight: 700;
  letter-spacing: -0.01em;
}
.sh.big .c {
  font-size: 14px;
}
.sh.big .s {
  font-size: 13px;
}
@media (max-width: 760px) {
  .sh.big .t {
    font-size: 18px;
  }
}

/* 분류·오늘의 키워드(ReportSummary)가 '오늘 리포트' 섹션 안으로 들어오면서
   .sec 안에 .sec가 겹칩니다 — 안쪽 섹션의 여백·테두리·배경만 지웁니다. */
.sec .sec {
  padding: 0;
  margin: 0 0 18px;
  border: 0;
  background: transparent;
  box-shadow: none;
}

/* 모달 안 다운로드 버튼 (.rdm-dl) */
.rdm-item {
  margin-bottom: 4px;
}
.rdm-dl {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  margin: -4px 0 18px;
  padding-left: 2px;
}
.rdm-dl .dlbtn {
  padding: 6px 12px;
  font-size: 13px;
}
.rdm-dl.whole {
  margin: 14px 0 18px;
  padding: 12px 0;
  border-top: 1px solid var(--line, #e3e6e5);
  border-bottom: 1px solid var(--line, #e3e6e5);
}
.rdm-dl.whole .lb {
  font-size: 13px;
  font-weight: 600;
  margin-right: 4px;
}
.rdm-dl .ext {
  opacity: .55;
  font-size: 12px;
}

.sh.big .t { color: #175243; }
:root[data-theme="dark"] .sh.big .t { color: #5fd4b0; }